-- [17/21] MIGRATION: 20260810055448_add_admin_update_policies_for_verification.sql
-- =============================================================================

/*
# Add admin UPDATE policies for verification workflow

## Problem
The RLS UPDATE policies on `profiles`, `nurse_profiles`, and `hospitals`
only allow the row owner to update (`auth.uid() = id`). When an admin
clicks Verify/Reject in the Admin Portal, the update is silently blocked
by RLS because the admin's auth.uid() does not match the target profile's
id. The verification never takes effect.

## Fix
Add admin-scoped UPDATE policies on all three tables. These allow any
authenticated user whose profile role is 'admin' to update rows, alongside
the existing owner-only policies. Both policies are permissive (OR logic),
so the owner can still update their own row and the admin can update any
row for verification purposes.

## Data Safety
- No tables created or deleted.
- No columns added, removed, or renamed.
- No data modified.
- RLS remains enabled on all tables.
- Existing owner UPDATE policies are preserved.
*/

-- ============ profiles: admin can update ============
DROP POLICY IF EXISTS "profiles_update_admin" ON profiles;
CREATE POLICY "profiles_update_admin" ON profiles FOR UPDATE
  TO authenticated USING (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  ) WITH CHECK (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  );

-- ============ nurse_profiles: admin can update ============
DROP POLICY IF EXISTS "nurse_profiles_update_admin" ON nurse_profiles;
CREATE POLICY "nurse_profiles_update_admin" ON nurse_profiles FOR UPDATE
  TO authenticated USING (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  ) WITH CHECK (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  );

-- ============ hospitals: admin can update ============
DROP POLICY IF EXISTS "hospitals_update_admin" ON hospitals;
CREATE POLICY "hospitals_update_admin" ON hospitals FOR UPDATE
  TO authenticated USING (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  ) WITH CHECK (
    EXISTS (SELECT 1 FROM profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
  );

-- =============================================================================
-- [18/21] MIGRATION: 20260811070136_enforce_interview_before_selection.sql
-- =============================================================================

/*
# Enforce interview-before-selection workflow at the database level

## Problem
A hospital can set an application status to 'selected' directly from
'shortlisted', bypassing the interview stage entirely. The UI should
prevent this, but we also need a database-level guard so the rule
cannot be bypassed by any client.

## Fix
Add a BEFORE UPDATE trigger on `applications` that rejects any update
to status = 'selected' unless a related interview exists with
status = 'completed'. This is the server-side enforcement that
complements the UI hiding of the Select button.

## Data Safety
- No tables created or deleted.
- No columns added, removed, or renamed.
- No data modified.
- RLS unchanged.
- Existing applications and interviews preserved.
*/

CREATE OR REPLACE FUNCTION public.enforce_interview_before_selection()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Only enforce when transitioning TO 'selected'
  IF NEW.status = 'selected' AND OLD.status <> 'selected' THEN
    -- Must have at least one completed interview for this application
    IF NOT EXISTS (
      SELECT 1 FROM interviews
      WHERE interviews.application_id = NEW.id
        AND interviews.status = 'completed'
    ) THEN
      RAISE EXCEPTION 'Cannot select an applicant without a completed interview';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trigger_enforce_interview_before_selection ON applications;
CREATE TRIGGER trigger_enforce_interview_before_selection
  BEFORE UPDATE ON applications
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_interview_before_selection();

-- Revoke execute from anon/authenticated so it can only be called by the trigger
REVOKE EXECUTE ON FUNCTION public.enforce_interview_before_selection() FROM anon, authenticated;

